import java.io.*;import java.net.*;import java.nio.channels.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;import java.lang.reflect.*;
import vn.rtr.aeris.control01.*;import vn.rtr.aeris.betaintegrated01.*;import vn.rtr.aeris.beta01runtime.*;
/** TEST ONLY: real Owner/Session/Authority/journal, fake Connection/clock. No flight-preflight claim. */
public final class OwnerOrderMock {
 static final String SOURCE="touch-11111111-1111-1111-1111-111111111111";static File root;static List<Map<String,Object>>results=new ArrayList<>(),metrics=new ArrayList<>();
 interface Op{void run()throws Exception;}static void check(boolean b,String why){if(!b)throw new AssertionError(why);}static void test(String id,Op op){try{op.run();results.add(Values.map("id",id,"pass",true));}catch(Throwable e){results.add(Values.map("id",id,"pass",false,"error",e.toString()));}}
 static ControlSession session(ControlOwner o)throws Exception{Field f=ControlOwner.class.getDeclaredField("session");f.setAccessible(true);return(ControlSession)f.get(o);}static ControlAuthority authority(ControlOwner o)throws Exception{Field f=ControlSession.class.getDeclaredField("authority");f.setAccessible(true);return(ControlAuthority)f.get(session(o));}
 static String lastKind(File run)throws IOException{File[]files=run.listFiles((d,n)->n.startsWith("segment-")&&n.endsWith(".jsonl"));if(files==null||files.length==0)return"";Arrays.sort(files);List<String>lines=Files.readAllLines(files[files.length-1].toPath());if(lines.isEmpty())return"";String s=lines.get(lines.size()-1);for(String k:new String[]{"CONTROL_LOOP_OBSERVATION","CONTROL_INPUT"})if(s.contains("\"kind\":\""+k+"\""))return k;return"";}
 static String allLines(File files)throws Exception{StringBuilder b=new StringBuilder();try(java.util.stream.Stream<Path>s=Files.walk(files.toPath())){s.filter(p->p.toString().endsWith(".jsonl")).sorted().forEach(p->{try{b.append(new String(Files.readAllBytes(p),"UTF-8"));}catch(Exception e){throw new RuntimeException(e);}});}return b.toString();}
 static String inputPayloads(String raw){StringBuilder b=new StringBuilder();for(String line:raw.split("\n"))if(line.contains("\"kind\":\"CONTROL_INPUT\"")){java.util.regex.Matcher m=java.util.regex.Pattern.compile("\"base64\":\"([^\"]*)\"").matcher(line);if(m.find())b.append(new String(Base64.getDecoder().decode(m.group(1)),java.nio.charset.StandardCharsets.UTF_8));}return b.toString();}
 static class Case implements ControlOwner.Connection {
  final String mode;final boolean expectedFresh;final File files;final AtomicLong ns=new AtomicLong(1000000000L);final ControlOwner[]owner=new ControlOwner[1];final ControlConfig config;volatile boolean closed,seeded,delayDone;volatile String finalState;volatile int writes,reads;volatile Boolean freshAtRead;volatile long sampleProducer,checkAtRead;
  Case(String mode,boolean expected)throws Exception{this.mode=mode;expectedFresh=expected;files=new File(root,mode);check(files.mkdir(),"exclusivecase");config=new ControlConfig(mode,ProfileFixture.specs());}
  ControlAuthority.Input input(long seq,long producer){return new ControlAuthority.Input(config.context,SOURCE,"ANDROID_UPTIME_NS_SAMPLER","ROOT_INJECTED_ANDROID_TOUCH",seq,producer,producer,0,new double[4],0,-1,false);}
  void seed()throws Exception{ControlSession s=session(owner[0]);s.observeLoop(ns.get());ControlAuthority a=authority(owner[0]);a.accept(input(1,ns.get()),ns.get());a.consent(ns.get(),"TEST_EXPLICIT_NEUTRAL_CONSENT");ns.set(mode.equals("already-expired")?1201000000L:mode.equals("loop-gap")?1700000000L:mode.equals("action-deadline")?12000000000L:1090000000L);sampleProducer=1050000000L;if(mode.equals("action-deadline"))owner[0].action("GUIDED","TEST_QUEUED_GUIDED",null,sampleProducer);else owner[0].input(input(2,sampleProducer));if(mode.equals("close-pending")){owner[0].action("GUIDED","TEST_QUEUED_GUIDED",null,sampleProducer);owner[0].close("EXPLICIT_OPERATOR_CLOSE");}seeded=true;}
  public InputStream input(){return new InputStream(){public int read(){return-1;}public int read(byte[]b,int o,int n)throws IOException{reads++;try{ControlAuthority a=authority(owner[0]);checkAtRead=ns.get();if(mode.equals("input-durability-stall")){int before=writes;boolean refused=false;try{session(owner[0]).action("LAND","TEST_FRESH_LAND_AFTER_STALL",null,ns.get());}catch(IllegalStateException e){refused=e.getMessage().contains("NO_FRESH_CONTROL_LEASE");}check(refused&&writes==before,"expiredinputmustrefuseactualSessionLANDbeforewire");}try{ControlAuthority.Input i=a.requireFresh(ns.get());freshAtRead=true;check(i.sequence==2&&i.elapsedNs==sampleProducer,"producerretimestamporinputloss");}catch(IllegalStateException e){freshAtRead=false;}owner[0].close("EXPLICIT_OPERATOR_CLOSE");throw new SocketTimeoutException("MOCK_READ_TIMEOUT");}catch(IOException e){throw e;}catch(Exception e){throw new IOException(e);}}};}
  public OutputStream output(){return new OutputStream(){public void write(int b){}public void write(byte[]b,int o,int n)throws IOException{writes++;try{if(writes==7)seed();if(mode.equals("unknown-send")&&writes==8)throw new IOException("MOCK_CALLBACK_ENTERED_WRITE_UNKNOWN");}catch(IOException e){throw e;}catch(Exception e){throw new IOException(e);}}};}
  public boolean isClosed(){return closed;}public void close(){closed=true;}
  void run()throws Exception{
   RunLifecycle.Clock clock=new RunLifecycle.Clock(){public long monotonicNs(){return ns.get();}public long wallUtcMs(){return 1700000000000L+ns.get()/1000000;}};
   NativeSegments.Sync sync=new NativeSegments.Sync(){public void file(FileDescriptor fd)throws IOException{fd.sync();if(!seeded||delayDone)return;String k=lastKind(new File(new File(files,"control-runs"),mode));if(mode.equals("timely-queued")&&k.equals("CONTROL_LOOP_OBSERVATION")){delayDone=true;ns.addAndGet(135000000L);}if(mode.equals("input-durability-stall")&&k.equals("CONTROL_INPUT")){delayDone=true;ns.addAndGet(220000000L);}}public void directory(File d)throws IOException{try(FileChannel c=FileChannel.open(d.toPath(),StandardOpenOption.READ)){c.force(true);}}};
   owner[0]=new ControlOwner(files,config,clock,sync,()->true,(id,state)->finalState=state,SOURCE,()->this);owner[0].start();Field f=ControlOwner.class.getDeclaredField("thread");f.setAccessible(true);Thread thread=(Thread)f.get(owner[0]);thread.join(5000);check(!thread.isAlive(),"boundedownerthread");check(closed&&finalState!=null,"connectionclosure");String raw=allLines(files);StringBuilder decoded=new StringBuilder();for(String line:raw.split("\n")){java.util.regex.Matcher x=java.util.regex.Pattern.compile("\"base64\":\"([^\"]*)\"").matcher(line);if(x.find())decoded.append(new String(Base64.getDecoder().decode(x.group(1)),java.nio.charset.StandardCharsets.UTF_8));}String events=decoded.toString();metrics.add(Values.map("mode",mode,"freshAtRead",freshAtRead,"expectedFresh",expectedFresh,"producerNs",sampleProducer,"freshnessCheckNs",checkAtRead,"injectedDelayOccurred",delayDone,"wireCalls",writes,"FDClosed",closed));
   if(mode.equals("unknown-send")){check(finalState.contains("MOCK_CALLBACK_ENTERED_WRITE_UNKNOWN")&&raw.contains("\"kind\":\"TX_UNKNOWN\""),"unknownsendmustremainunknown");return;}
   if(mode.equals("action-deadline")){check(finalState.contains("CONTROL_SESSION_DEADLINE")&&writes==7&&!events.contains("TEST_QUEUED_GUIDED"),"queuedactionmustnotbypassrundeadorwrite");return;}
   if(mode.equals("close-pending")){check(writes==7&&!inputPayloads(raw).contains("\"sequence\":2")&&!events.contains("TEST_QUEUED_GUIDED")&&events.contains("\"queuedMessagesNotDurablyAdmitted\":2"),"closemustblockallpendingcallbacks");return;}
   if(mode.equals("loop-gap")){check(finalState.contains("CONTROL_LOOP_IO_GAP"),"500msguardweakened");return;}
   check(freshAtRead!=null&&freshAtRead==expectedFresh,"freshnessoutcome expected="+expectedFresh+" got="+freshAtRead+" final="+finalState);check(finalState.contains("\"consent\":false")&&finalState.contains("\"grants\":1"),"noimplicitregrant");check(inputPayloads(raw).contains("\"sequence\":2")&&inputPayloads(raw).contains("\"elapsedNs\":1050000000"),"originalproducerretained");
   if(expectedFresh)check(!events.contains("INPUT_LEASE_EXPIRED_BEFORE_NEW_SAMPLE"),"timelyinputunnecessarilyexpired");else check(events.contains("INPUT_LEASE_EXPIRED"),"actualexpiryshouldrevoke");
  }
 }
 public static void main(String[]args)throws Exception{root=new File(args[0]);check(root.mkdir(),"exclusiveroot");boolean baseline=args.length>1&&args[1].equals("baseline");test("timely-queued-135ms-observation-fsync",()->new Case("timely-queued",!baseline).run());if(!baseline){test("already-expired-no-regrant",()->new Case("already-expired",false).run());test("input-own-durability220ms-no-backdate",()->new Case("input-durability-stall",false).run());test("unknown-send-retained",()->new Case("unknown-send",false).run());test("loopgap500ms-still-fails",()->new Case("loop-gap",false).run());test("queued-explicit-action-after-rundeadline",()->new Case("action-deadline",false).run());test("close-pending-blocks-all-queued-input-action",()->new Case("close-pending",false).run());}System.out.println(Values.json(Values.map("results",results,"metrics",metrics,"scope","ACTUAL_OWNER_SESSION_AUTHORITY_REAL_FSYNC_TEST_FIXTURE_AUTHORITY_SEED_FAKE_CONNECTION_CLOCK_NO_ANDROID_PREFLIGHT_OR_FLIGHT_ACCEPTANCE")));}
}
